import heapq
from collections import deque


def maxSafeness(grid):
    n = len(grid)
    safe = [[-1] * n for _ in range(n)]
    q = deque()
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                safe[r][c] = 0
                q.append((r, c))
    while q:
        y, x = q.popleft()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < n and 0 <= nx < n and safe[ny][nx] == -1:
                safe[ny][nx] = safe[y][x] + 1
                q.append((ny, nx))
    best = [[-1] * n for _ in range(n)]
    best[0][0] = safe[0][0]
    heap = [(-safe[0][0], 0, 0)]
    while heap:
        neg, y, x = heapq.heappop(heap)
        s = -neg
        if s < best[y][x]:
            continue
        if y == n - 1 and x == n - 1:
            return s
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < n and 0 <= nx < n:
                ns = min(s, safe[ny][nx])
                if ns > best[ny][nx]:
                    best[ny][nx] = ns
                    heapq.heappush(heap, (-ns, ny, nx))
    return 0
